"""Client that posts records to the ingestion API."""
import json
import os
import sys
import urllib.error
import urllib.request

# The ingestion endpoint is not recorded anywhere in this repo, and none was
# found in the environment or any config file on this host either. Rather
# than hard-coding a guessed URL (which would risk shipping real record data,
# including emails, to an unknown/untrusted host), the endpoint must be
# supplied explicitly via the INGEST_ENDPOINT environment variable.
ENDPOINT = os.environ.get("INGEST_ENDPOINT", "")


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_records(endpoint, records):
    if not endpoint:
        raise RuntimeError(
            "No ingestion endpoint configured. Set the INGEST_ENDPOINT "
            "environment variable to the ingestion API URL before running "
            "this script."
        )

    accepted = 0
    for record in records:
        body = json.dumps(record).encode("utf-8")
        req = urllib.request.Request(
            endpoint, data=body, headers={"Content-Type": "application/json"}
        )
        try:
            with urllib.request.urlopen(req, timeout=10) as resp:
                if resp.status in (200, 201, 202):
                    accepted += 1
        except urllib.error.URLError as exc:
            print(f"failed to post record {record!r}: {exc}", file=sys.stderr)
    return accepted


def main():
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
